hsd:
Geometry = GenFormat {
  <<< "geo.gen"
}
Hamiltonian = DFTB {
  SCC = Yes
  SCCTolerance = 1.7e-10
  MaxSCCIterations = 500
  ShellResolvedSCC = No
  Charge = 0.0
  SlaterKosterFiles = Type2FileNames {
    Prefix = "/tmp/pydftb_ref_ixcbf599/plain/"
    Separator = "-"
    Suffix = ".skf"
  }
  MaxAngularMomentum {
    O = "p"
    H = "s"
  }
  Filling = Fermi {
    Temperature [K] = 0.0
  }
  KPointsAndWeights = {
    0.0 0.0 0.0 1.0
  }
  EwaldTolerance = 1e-12

}
Analysis {
  AtomResolvedEnergies = Yes
  WriteNetCharges = Yes
  CM5 {}
  ElectrostaticPotential {
    Grid [Angstrom] {
      Spacing = 1.5 1.5 1.5
      Origin = 0.0 0.0 0.0
      GridPoints = 3 2 2
    }
  }
  WriteEigenvectors = Yes
  EigenvectorsAsText = Yes
  PrintForces = Yes
  MullikenAnalysis = Yes
}
Options {
  WriteDetailedOut = Yes
  WriteResultsTag = Yes
  WriteAutotestTag = Yes
  TimingVerbosity = 0
}
ParserOptions {
  ParserVersion = 14
}
Parallel {
  UseOmpThreads = Yes
}
